<div style="margin-top:0.5rem; display:flex; gap:0.5rem; align-items:center;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
    <span>@_statusMessage</span>
</div>

@code {
    private string _content = string.Empty;
    private string? _lastSavedContent;
    private string _statusMessage = string.Empty;
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;
    private Timer? _autoSaveTimer;

    private bool HasUnsavedChanges => _content != _lastSavedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            _dotNetRef = DotNetObjectReference.Create(this);
            await _interop.InitializeAsync(_dotNetRef);

            _autoSaveTimer = new Timer(async _ =>
            {
                await InvokeAsync(async () =>
                {
                    if (HasUnsavedChanges)
                    {
                        await SaveContentAsync();
                        StateHasChanged();
                    }
                });
            }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    [JSInvokable]
    public async Task OnContentRestored(string content)
    {
        await InvokeAsync(() =>
        {
            _content = content;
            _lastSavedContent = content;
            _statusMessage = "Content restored from previous session.";
            StateHasChanged();
        });
    }

    private async Task SaveNowAsync()
    {
        await SaveContentAsync();
    }

    private async Task SaveContentAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(_content);
        _lastSavedContent = _content;
        _statusMessage = $"Last saved at {DateTime.Now:HH:mm:ss}";

        await _interop.DisableBeforeUnloadAsync();
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        _content = string.Empty;
        _lastSavedContent = string.Empty;
        _statusMessage = string.Empty;

        await _interop.ClearAsync();
        await _interop.DisableBeforeUnloadAsync();
    }

    protected override async Task OnAfterRenderAsync_UpdateBeforeUnload()
    {
        // This is handled via the input event below
    }

    // We need to manage the beforeunload listener whenever content changes.
    // Since @bind:event="oninput" triggers re-renders, we track it here.
    private async Task UpdateBeforeUnloadGuard()
    {
        if (_interop is null) return;

        if (HasUnsavedChanges)
            await _interop.EnableBeforeUnloadAsync();
        else
            await _interop.DisableBeforeUnloadAsync();
    }

    async ValueTask IAsyncDisposable.DisposeAsync()
    {
        _autoSaveTimer?.Dispose();

        if (_interop is not null)
            await _interop.DisposeAsync();

        _dotNetRef?.Dispose();
    }
}

